// expect: exit 1
// screen: 0 dice ok
int main(void)
{
    int i, n, ok = 1;
    srand(7);
    for (i = 0; i < 50; i++) {
        n = rand() % 6 + 1;
        if (n < 1 || n > 6)
            ok = 0;
    }
    cls();
    print(ok ? "dice ok" : "dice bad");
    return ok;
}
